/**
 * Enrollment clearance desk: isometric drawing generated by the /isometric skill.
 * Style: Two-tone (light). Self-contained: no dependencies beyond React.
 *
 * Editable model: `./clearance-desk.model.ts`
 * Re-theme with the tokens prop (ink, face, plinth, accent, bg) or by
 * overriding any --iso-* CSS variable on the element.
 */
import * as React from "react";
import { CLEARANCE_DESK_BODY } from "./clearance-desk.svg-body";

type Tokens = {
  ink?: string;
  face?: string;
  plinth?: string;
  accent?: string;
  bg?: string;
};

export interface ClearanceDeskProps
  extends Omit<React.SVGProps<SVGSVGElement>, "ref"> {
  /** Width in px (or any CSS length). Height follows the aspect ratio. Default: 100% of the container. */
  size?: number | string;
  /** Base colours. Every shade is derived from these. */
  tokens?: Tokens;
  /** Line weight in px at the displayed size. */
  weight?: number;
  /** Motion: play on hover, loop forever, or stay still. */
  animate?: "hover" | "loop" | false;
  /** Accessible name. */
  title?: string;
}

const BASE: Required<Tokens> = {
  bg: "#051d37",
  ink: "#0b2340",
  face: "#fdfcf9",
  plinth: "#c7d7c3",
  accent: "#f5a623",
};

/** Every colour in the drawing, as an expression over the base tokens. */
const SLOTS: Record<string, string> = {
  line: "ink",
  "face-l": "face>0.1",
  "face-t": "face>0.06",
  "face-r": "face>0.17",
  soft: "ink~face:0.55",
  "detail-l": "face>0.19",
  "detail-t": "face>0.14",
  "detail-r": "face>0.26",
  "body-t": "face",
  "body-l": "face>0.05",
  "body-r": "face>0.12",
  "ink-l": "ink~face:0.08",
  "accent-l": "accent",
  "accent-t": "accent<0.2",
  "ink-t": "ink~face:0.18",
  "ink-r": "ink",
  "accent-r": "accent>0.14",
};

function mix(a: string, b: string, t: number): string {
  const p = (h: string) => {
    h = h.replace("#", "");
    if (h.length === 3)
      h = h
        .split("")
        .map((c) => c + c)
        .join("");
    return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16));
  };
  const A = p(a),
    B = p(b);
  return (
    "#" +
    A.map((v, i) =>
      Math.round(Math.min(255, Math.max(0, v + (B[i] - v) * t)))
        .toString(16)
        .padStart(2, "0"),
    ).join("")
  );
}

function slot(expr: string, base: Record<string, string>): string {
  const m = /^([a-z]+)(?:([<>])([\d.]+)|~([a-z]+):([\d.]+))?$/.exec(expr)!;
  const c = base[m[1]];
  if (m[2] === ">") return mix(c, "#000000", +m[3]);
  if (m[2] === "<") return mix(c, "#ffffff", +m[3]);
  if (m[4]) return mix(c, base[m[4]], +m[5]);
  return mix(c, c, 0);
}

export default function ClearanceDesk({
  size,
  tokens,
  weight = 1,
  animate = "hover",
  title = "Enrollment clearance desk",
  style,
  ...rest
}: ClearanceDeskProps) {
  const id = "iso" + React.useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const base = { ...BASE, ...tokens } as Record<string, string>;
  const vars: Record<string, string> = {};
  for (const k in SLOTS) vars["--iso-" + k] = slot(SLOTS[k], base);
  const css = `#${id} path,#${id} circle{vector-effect:non-scaling-stroke;stroke-linejoin:round;stroke-linecap:round}#${id} .s{stroke-width:0.9px}#${id} .o{stroke-width:${weight}px}#${id} .d{stroke-width:${weight * 0.75}px}@keyframes ${id}-stamp{0%,100%{transform:translate(0,0)}42%,58%{transform:translate(0,8.4px)}}@keyframes ${id}-ticket{0%,100%{transform:translate(0,0)}45%,65%{transform:translate(-5.82px,3.36px)}}#${id}[data-animate="loop"] .iso-g-stamp,#${id}[data-animate="hover"]:hover .iso-g-stamp,#${id}[data-animate="hover"]:focus-visible .iso-g-stamp{animation:${id}-stamp 2.4s cubic-bezier(0.34,1.56,0.64,1) infinite}#${id}[data-animate="loop"] .iso-g-ticket,#${id}[data-animate="hover"]:hover .iso-g-ticket,#${id}[data-animate="hover"]:focus-visible .iso-g-ticket{animation:${id}-ticket 2.4s cubic-bezier(0.22,1,0.36,1) infinite}@media (prefers-reduced-motion: reduce){#${id} .iso-g-stamp,#${id} .iso-g-ticket{animation:none!important}}`;
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="-148.86 -150.87 297.73 241.05"
      id={id}
      role="img"
      aria-labelledby={`${id}-t ${id}-d`}
      data-animate={animate || undefined}
      tabIndex={animate === "hover" ? 0 : undefined}
      width={size ?? "100%"}
      style={{ height: "auto", ...(vars as React.CSSProperties), ...style }}
      {...rest}
    >
      <title id={`${id}-t`}>{title}</title>
      <desc id={`${id}-d`}>
        An enrollment clearance desk: a live queue monitor and ticket dispenser
        on the left, a six-step requirements clipboard at the centre with an
        officer's gold rubber stamp poised over the verification seal,
        requirement folders in an organizer tray at the back right, and a stack
        of student ID cards in the foreground.
      </desc>
      <style>{css}</style>
      <g dangerouslySetInnerHTML={{ __html: CLEARANCE_DESK_BODY }} />
    </svg>
  );
}
